INSERT INTO "ExerciseSourceReference" (
  "exerciseRevisionId", "sourceId", "externalReference", "factualNotes", "accessedAt"
)
SELECT
  r.id,
  s.id,
  'https://www.who.int/news-room/fact-sheets/detail/physical-activity',
  'Рекомендации ВОЗ по безопасной физической активности и постепенному выбору посильной интенсивности.',
  now()
FROM "ExerciseRevision" r
JOIN "Exercise" e ON e.id = r."exerciseId"
JOIN "ExerciseCatalogSource" s ON s.code = 'who-physical-activity'
WHERE e.key = 'morning_walk'
  AND r."revisionNumber" = 2
  AND r.status = 'DRAFT'
  AND r."createdBy" = 'system:workout-catalog-01b'
  AND NOT EXISTS (
    SELECT 1 FROM "ExerciseSourceReference" x
    WHERE x."exerciseRevisionId" = r.id AND x."sourceId" = s.id
  );

