-- ---------------------------------------------------------------------------
-- G. Approve DRAFT revisions (triggers set approvedAt)
-- ---------------------------------------------------------------------------
UPDATE "ExerciseRevision" r
SET status = 'APPROVED',
    "reviewedAt" = COALESCE(r."reviewedAt", now())
WHERE r.status = 'DRAFT'
  AND r."createdBy" = 'system:workout-catalog-01b'
  AND EXISTS (
    SELECT 1 FROM "ExerciseSafetyProfile" sp WHERE sp."exerciseRevisionId" = r.id
  )
  AND EXISTS (
    SELECT 1 FROM "ExerciseSourceReference" sr WHERE sr."exerciseRevisionId" = r.id
  );

-- ---------------------------------------------------------------------------
-- H. Candidate / variant graph (content basis for 01D)
-- ---------------------------------------------------------------------------
INSERT INTO "ExerciseVariantRelation" (
  "fromExerciseId", "toExerciseId", "relationType", priority, "levelDelta", active
)
SELECT src.id, dst.id, 'SAME_LEVEL', 0, 0, true
FROM "Exercise" src
JOIN "Exercise" dst ON dst.key = 'recovery_walk'
