  AND f.key IN ('morning_walk', 'bodyweight_squats', 'stretching', 'light_jog', 'core_plank', 'mobility_flow', 'recovery_walk', 'push_ups', 'glute_bridge', 'dead_bug', 'band_row', 'band_pull_apart', 'dumbbell_row', 'goblet_squat', 'machine_leg_press', 'cable_row', 'treadmill_walk', 'chest_press_machine', 'barbell_romanian_deadlift', 'lat_pulldown', 'chair_sit_to_stand', 'wall_sit', 'box_squat_to_chair', 'dumbbell_romanian_deadlift', 'bodyweight_hip_thrust', 'barbell_hip_thrust', 'good_morning_bodyweight', 'supported_reverse_lunge', 'reverse_lunge', 'static_split_squat', 'low_step_up', 'dumbbell_step_up', 'knee_push_ups', 'incline_push_ups', 'dumbbell_floor_press', 'barbell_bench_press', 'dumbbell_shoulder_press', 'seated_machine_shoulder_press', 'band_overhead_press', 'band_face_pull', 'seated_cable_row', 'chest_supported_dumbbell_row', 'barbell_bent_over_row', 'assisted_pull_up_machine', 'band_lat_pulldown', 'forearm_plank_knees', 'bird_dog', 'side_plank_knee', 'side_plank', 'pallof_press_band', 'heel_taps', 'dead_bug_hold', 'side_lying_clamshell', 'band_lateral_walk', 'glute_bridge_march', 'standing_calf_raise', 'seated_calf_raise_machine', 'farmer_carry_dumbbell', 'suitcase_carry_dumbbell', 'brisk_outdoor_walk', 'stationary_bike_easy', 'elliptical_easy', 'seated_march', 'cat_cow_flow', 'hip_flexor_stretch', 'thoracic_opener_open_book', 'diaphragmatic_breathing', 'supine_knee_hugs', 'seated_leg_curl_machine', 'leg_extension_machine', 'cable_chest_press', 'pec_deck_machine', 'lat_pulldown_neutral_grip', 'band_squat', 'band_glute_bridge', 'band_chest_press', 'dumbbell_goblet_split_squat', 'dumbbell_lateral_raise', 'machine_hip_abduction', 'back_extension_machine', 'standing_band_row', 'mat_glute_bridge_hold', 'wall_angels', 'ankle_rocks')
  AND NOT EXISTS (
    SELECT 1 FROM allowed a
    WHERE a.from_key = f.key
      AND a.to_key = t.key
      AND a.relation_type = vr."relationType"
  );

