FROM "WorkoutCatalogRelease" rel
JOIN "Exercise" e ON e.key = 'dumbbell_floor_press'
JOIN "ExerciseRevision" r
  ON r."exerciseId" = e.id
 AND r."revisionNumber" = 1
 AND r.status = 'APPROVED'
WHERE rel.code = 'workout-catalog-canonical-01b'
  AND rel.status = 'DRAFT'
  AND e."familyId" IS NOT NULL
ON CONFLICT ("releaseId", "exerciseId") DO NOTHING;

