-- ---------------------------------------------------------------------------
-- J. Atomic publish under advisory lock 21000101
-- ---------------------------------------------------------------------------
DO $publish$
BEGIN
  PERFORM pg_advisory_xact_lock(21000101);

  IF NOT EXISTS (
    SELECT 1 FROM "WorkoutCatalogRelease"
    WHERE code = 'workout-catalog-canonical-01b' AND status = 'DRAFT'
  ) THEN
    -- Already published or absent: idempotent no-op for publish step.
    RETURN;
  END IF;

  IF (
    SELECT COUNT(*) FROM "WorkoutCatalogReleaseItem" i
    JOIN "WorkoutCatalogRelease" rel ON rel.id = i."releaseId"
    WHERE rel.code = 'workout-catalog-canonical-01b'
  ) <> 84 THEN
    RAISE EXCEPTION 'WORKOUT_CATALOG_01B_RELEASE_ITEM_COUNT';
  END IF;

  UPDATE "WorkoutCatalogRelease"
  SET status = 'RETIRED',
      "retiredAt" = COALESCE("retiredAt", now())
  WHERE status = 'PUBLISHED'
    AND code <> 'workout-catalog-canonical-01b';

  UPDATE "WorkoutCatalogRelease"
  SET status = 'PUBLISHED',
      "publishedAt" = COALESCE("publishedAt", now()),
      "retiredAt" = NULL
  WHERE code = 'workout-catalog-canonical-01b'
    AND status = 'DRAFT';

  IF (SELECT COUNT(*) FROM "WorkoutCatalogRelease" WHERE status = 'PUBLISHED') <> 1 THEN
    RAISE EXCEPTION 'WORKOUT_CATALOG_01B_PUBLISHED_COUNT';
  END IF;
END
$publish$;

